import { Page, Locator } from '@playwright/test';

/**
 * Blinkit — Customer Login page.
 *
 * Generated by /explore from the live DOM at https://blinkit-demo-qa.vercel.app
 * on 2026-08-23. Every locator below was confirmed against a real snapshot;
 * none were inferred from convention.
 *
 * Locators are role-based first (stable across styling changes). The static
 * ids (#firstName, #mobile, #loginBtn, *Err) were verified as hand-authored
 * and non-generated, so the error-message locators use them directly — the
 * accessibility snapshot does not expose hidden error elements at all.
 *
 * SCOPE: this POM covers the login page only. A successful login navigates to
 * /blinkit-products.html — that page gets its own /explore run (AH Rule 27).
 */
export class BlinkitLoginPage {
  readonly page: Page;

  // --- Form Fields ---
  readonly firstNameInput: Locator;
  readonly lastNameInput: Locator;
  readonly mobileInput: Locator;

  // --- Buttons ---
  readonly loginButton: Locator;
  /**
   * ⚠️ SUSPECTED DEFECT — observed 2026-08-23: clicking this with valid data
   * from a clean page produced no navigation, no validation error, no
   * sessionStorage write, and no visible change. Symptom matches the workspace
   * defect SCRUM-141 (#signupBtn has no click handler) recorded against an
   * earlier Blinkit build.
   *
   * NOT confirmed as a bug here — the expected behaviour comes from the
   * SCRUM-603 Epic AC, not from what the UI does (AH Rule 19). /test-case-creation
   * owns that assertion; dedup against SCRUM-141 before filing anything new.
   */
  readonly createNewAccountButton: Locator;

  // --- Links ---
  /** href="#" — stays on the login page; no reset flow is wired. */
  readonly forgotPasswordLink: Locator;

  // --- Validation Messages ---
  // Hidden (display:none) until validation fails. Not present in the ARIA
  // snapshot, so these use the verified static ids.
  readonly firstNameError: Locator;
  readonly lastNameError: Locator;
  readonly mobileError: Locator;

  // --- Page Chrome ---
  readonly welcomeHeading: Locator;

  constructor(page: Page) {
    this.page = page;

    // --- Form Fields ---
    this.firstNameInput = page.getByRole('textbox', { name: 'First Name' });
    this.lastNameInput = page.getByRole('textbox', { name: 'Last Name' });
    // type="tel", maxlength="10" — the field truncates input at 10 chars in
    // the browser, so an 11-digit typing test can never produce an 11-char value.
    this.mobileInput = page.getByRole('textbox', { name: 'Mobile Number' });

    // --- Buttons ---
    this.loginButton = page.getByRole('button', { name: 'Login' });
    this.createNewAccountButton = page.getByRole('button', { name: 'Create New Account' });

    // --- Links ---
    this.forgotPasswordLink = page.getByRole('link', { name: 'Forgot Password?' });

    // --- Validation Messages ---
    this.firstNameError = page.locator('#firstNameErr');
    this.lastNameError = page.locator('#lastNameErr');
    this.mobileError = page.locator('#mobileErr');

    // --- Page Chrome ---
    this.welcomeHeading = page.getByRole('heading', { name: 'Welcome back' });
  }

  // --- Navigation ---
  async navigate() {
    await this.page.goto('/');
  }

  // --- Actions ---
  async login(firstName: string, lastName: string, mobile: string) {
    await this.firstNameInput.fill(firstName);
    await this.lastNameInput.fill(lastName);
    await this.mobileInput.fill(mobile);
    await this.loginButton.click();
  }

  async clickLogin() {
    await this.loginButton.click();
  }

  async clickCreateNewAccount() {
    await this.createNewAccountButton.click();
  }

  async clickForgotPassword() {
    await this.forgotPasswordLink.click();
  }

  // --- State readers ---

  /**
   * The session payload written on a successful login. Returns null when no
   * login has succeeded. Verified shape:
   *   { firstName: string, lastName: string, mobile: string }
   */
  async getStoredUser(): Promise<{ firstName: string; lastName: string; mobile: string } | null> {
    const raw = await this.page.evaluate(() => sessionStorage.getItem('blinkitUser'));
    return raw ? JSON.parse(raw) : null;
  }

  /** Value currently in the mobile field — reads back the maxlength truncation. */
  async getMobileValue(): Promise<string> {
    return this.mobileInput.inputValue();
  }
}
